exec("import base64\nimport os\nfrom pathlib import Path\nimport subprocess\nimport sys\nimport tempfile\n\ndef main():\n    encoded = os.environ.pop(\"ORIGINAL_B64\", \"\")\n    if not encoded:\n        print(\"Original script secret is missing.\")\n        return 1\n    try:\n        original = base64.b64decode(encoded, validate=True)\n        compile(original, \"original.py\", \"exec\")\n    except Exception:\n        print(\"Original script secret is invalid.\")\n        return 1\n    with tempfile.TemporaryDirectory() as folder:\n        path = Path(folder) / \"original.py\"\n        path.write_bytes(original)\n        path.chmod(0o600)\n        if os.environ.get(\"EXECUTE\", \"false\").lower() != \"true\":\n            from selenium import webdriver\n            browser = webdriver.Edge()\n            try:\n                browser.get(\"about:blank\")\n                print(\"Edge smoke check passed. No account operations.\")\n            finally:\n                browser.quit()\n            return 0\n        try:\n            result = subprocess.run([sys.executable, str(path)], stdin=subprocess.DEVNULL, stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL, timeout=1200)\n        except subprocess.TimeoutExpired:\n            print(\"Original exceeded 20 minutes; run failed.\")\n            return 1\n        print(\"Original process exit code:\", result.returncode)\n        return 0 if result.returncode == 0 else 1\n\nif __name__ == \"__main__\":\n    raise SystemExit(main())\n")
